export function webShipping(weight, international) {
  const fixed = international ? 12 : 4;
  const perWeight = international ? 3 : 1;
  return fixed + weight * perWeight;
}
export function phoneShipping(weight, international) {
  const fixed = international ? 12 : 4;
  const perWeight = international ? 3 : 1;
  return fixed + weight * perWeight;
}

